struct TokenBucket {
    private let capacity: Double, refillPerSecond: Double
    private var tokens: Double
    private var lastRefill: ContinuousClock.Instant

    init(capacity: Int, refillPerSecond: Double, now: ContinuousClock.Instant = .now) {
        self.capacity = Double(capacity); self.refillPerSecond = refillPerSecond
        tokens = Double(capacity); lastRefill = now
    }

    mutating func tryConsume(now: ContinuousClock.Instant = .now) -> Bool {
        let elapsed = now - lastRefill
        let seconds = Double(elapsed.components.seconds) + Double(elapsed.components.attoseconds) / 1e18
        tokens = min(capacity, tokens + seconds * refillPerSecond)
        lastRefill = now
        guard tokens >= 1 else { return false }
        tokens -= 1
        return true
    }
}
